  let combined;
  for (const term of terms) {
    const fragments = [...new Set(Array.from({ length: term.length - 2 }, (_, i) => term.slice(i, i + 3)))];
    const lists = fragments.map(g => grams[g] ? decodePosting(grams[g], words.length) : []);
